INSERT INTO `assistant_knowledge` (`id`, `keywords`, `answer`, `category`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'فئات,حساسيه,abc', 'فئات الحساسية:\n• A — حرجة جداً.\n• B — متوسطة.\n• C — منخفضة.\nتُحدد عند إدخال الأصل وتؤثر على أولوية الصيانة.', 'تعاريف', 1, 1, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(2, 'دوره,دورة,دخول', 'دورة دخول الأصل:\n1) أمر شراء ← 2) استلام ← 3) تشغيل ← 4) تسجيل وتاج ← 5) عهدة ← 6) صيانة وجرد.', 'إرشاد', 1, 2, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(3, 'دوري,صلاحياتي', 'بصفتك مستخدماً معتمداً: ترفع البلاغات، تحدّث أصول قسمك، وتشارك في الجرد المسند إليك.', 'إرشاد', 1, 3, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(4, 'بلاغ,شكوي', 'لرفع بلاغ: «البلاغات» ← «رفع بلاغ» ← اربط الأصل ← الأولوية والوصف ← إرسال.', 'إرشاد', 1, 4, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(5, 'اصل,اضافه', 'لإضافة أصل: «الأصول» ← «إضافة أصل» ← التاج/السيريال/الفئة/القسم ← الحساسية والقيمة ← حفظ.', 'إرشاد', 1, 5, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(6, 'عهده,نقل', 'لنقل عهدة: «توزيع العهدة» ← اختر الأصل والموظف ← تأكيد التوقيع.', 'إرشاد', 1, 6, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(7, 'جرد', 'لبدء جرد: «الجرد» ← «جلسة جديدة» ← الأعضاء والأقسام ← المسح ← الاعتماد.', 'إرشاد', 1, 7, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(8, 'استلام', 'لمحضر استلام: «الاستلام» ← «محضر استلام» ← ربط أمر الشراء ← إرفاق واعتماد.', 'إرشاد', 1, 8, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(9, 'تقرير,تصدير,حفظ', 'لإصدار تقرير: افتح تقريراً ← فلاتر ← حفظ/تصدير ← مشاركة بالرابط.', 'إرشاد', 1, 9, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(10, 'sla,اتفاقيه', 'SLA: الحد الزمني المستهدف للاستجابة/الإصلاح؛ تجاوزه مؤشر سلبي.', 'تعاريف', 1, 10, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(11, 'mttr,متوسط,اصلاح', 'MTTR: متوسط زمن الإصلاح = الفرق بين البلاغ والإنجاز.', 'تعاريف', 1, 11, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(12, 'ضمان', 'راجع الأصول المنتهي ضمانها خلال 90 يوماً وارفع الأعطال قبل الانتهاء.', 'تعاريف', 1, 12, '2026-08-09 23:12:11', '2026-08-09 23:12:11'),
(13, 'التركيب والعهدة', 'الدخول الى - التركيب والعهدة من قبل فريق الصيانة المختص', 'إرشاد', 1, 0, '2026-08-09 23:59:31', '2026-08-09 23:59:31');
