CREATE TABLE `asset_custody_log` (
  `id` int(10) UNSIGNED NOT NULL,
  `asset_id` int(10) UNSIGNED NOT NULL,
  `from_type` enum('personal','dept','shared') DEFAULT NULL COMMENT 'NULL = أول إسناد عهدة (لم تكن معهودة)',
  `from_user_id` int(10) UNSIGNED DEFAULT NULL,
  `from_dept_id` int(10) UNSIGNED DEFAULT NULL,
  `to_type` enum('personal','dept','shared') NOT NULL,
  `to_user_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'إلزامي عند to_type=personal — يتحقق منه الكود',
  `to_dept_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'إلزامي عند to_type=dept — يتحقق منه الكود',
  `custody_date` date NOT NULL COMMENT 'تاريخ سريان العهدة',
  `reason` varchar(200) DEFAULT NULL COMMENT 'سبب النقل',
  `decision_ref` varchar(100) DEFAULT NULL COMMENT 'مرجع القرار/الخطاب',
  `notes` text DEFAULT NULL,
  `batch_id` varchar(36) DEFAULT NULL COMMENT 'معرّف الدفعة — يجمع أصول عملية النقل الجماعي الواحدة',
  `created_by` int(10) UNSIGNED NOT NULL COMMENT 'منفّذ العملية',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجل حركات عهد الأصول — لا يُحذف منه ولا يُعدَّل';

