--
-- بنية الجدول `asset_disposals`
--

CREATE TABLE `asset_disposals` (
  `id` int(10) UNSIGNED NOT NULL,
  `asset_id` int(10) UNSIGNED NOT NULL COMMENT 'FK → assets.id',
  `disposal_type` enum('scrap','destroy','sell','transfer_out') NOT NULL COMMENT 'scrap=تكهين, destroy=إتلاف, sell=بيع, transfer_out=نقل خارجي',
  `reason` enum('obsolete','damaged_beyond_repair','end_of_life','lost','replaced','other') NOT NULL COMMENT 'سبب التخلص',
  `reason_notes` text DEFAULT NULL COMMENT 'تفاصيل إضافية عن السبب',
  `committee_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'FK → committees.id (لجنة داخلية، اختياري)',
  `committee_reference` varchar(100) DEFAULT NULL COMMENT 'رقم قرار/محضر اللجنة (نص حر للتوثيق الورقي)',
  `committee_date` date DEFAULT NULL COMMENT 'تاريخ قرار اللجنة',
  `committee_chairman` varchar(150) DEFAULT NULL COMMENT 'رئيس اللجنة (denormalized)',
  `committee_members` text DEFAULT NULL COMMENT 'قائمة بأسماء الأعضاء (denormalized JSON array or comma-separated)',
  `decision_doc_number` varchar(100) DEFAULT NULL COMMENT 'رقم وثيقة القرار الرسمي',
  `disposal_date` date NOT NULL COMMENT 'تاريخ التنفيذ الفعلي للتخلص',
  `disposal_value` decimal(12,2) DEFAULT NULL COMMENT 'قيمة البيع (لحالة البيع فقط)',
  `attachments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'JSON: [{name,path,size,type}, ...]' CHECK (json_valid(`attachments`)),
  `notes` text DEFAULT NULL,
  `created_by` int(10) UNSIGNED NOT NULL COMMENT 'FK → users.id',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='قرارات التخلص من الأصول (نموذج 9+10)';

