--
-- بنية الجدول `complaints`
--

CREATE TABLE `complaints` (
  `id` int(10) UNSIGNED NOT NULL,
  `request_number` varchar(30) NOT NULL COMMENT 'مثال: CMP/2026/0001',
  `request_type` enum('medical','it','general') NOT NULL,
  `general_type` enum('asset','location') DEFAULT NULL COMMENT 'فقط عند request_type=general',
  `asset_id` int(10) UNSIGNED DEFAULT NULL,
  `location_description` varchar(255) DEFAULT NULL COMMENT 'بلاغ بلا جهاز محدد، نص حر للموقع',
  `dept_id` int(10) UNSIGNED NOT NULL COMMENT 'القسم المُبلِّغ',
  `priority` enum('normal','urgent','critical') NOT NULL DEFAULT 'normal',
  `description` text NOT NULL,
  `status` enum('open','acknowledged','in_progress','stalled','escalated','resolved','closed','cancelled','rejected') NOT NULL DEFAULT 'open',
  `requested_by` int(10) UNSIGNED NOT NULL,
  `acknowledged_by` int(10) UNSIGNED DEFAULT NULL,
  `acknowledged_at` datetime DEFAULT NULL,
  `started_by` int(10) UNSIGNED DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `stalled_by` int(10) UNSIGNED DEFAULT NULL,
  `stalled_at` datetime DEFAULT NULL,
  `stall_reason` text DEFAULT NULL,
  `escalated_by` int(10) UNSIGNED DEFAULT NULL,
  `escalated_at` datetime DEFAULT NULL,
  `escalation_note` text DEFAULT NULL,
  `escalation_due_at` datetime DEFAULT NULL COMMENT 'وقت استحقاق التصعيد التلقائي — يحسبه الكرون',
  `escalation_notified` tinyint(1) NOT NULL DEFAULT 0,
  `resolved_by` int(10) UNSIGNED DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `resolution_notes` text DEFAULT NULL,
  `resolution_rejected_reason` text DEFAULT NULL COMMENT 'المُبلِّغ رفض الحل المقترح فقط — ترجع الحالة in_progress، ليست حالة نهائية',
  `confirmed_by` int(10) UNSIGNED DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `service_rating` tinyint(3) UNSIGNED DEFAULT NULL COMMENT '1-5',
  `service_comment` text DEFAULT NULL,
  `closed_by` int(10) UNSIGNED DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `cancelled_by` int(10) UNSIGNED DEFAULT NULL COMMENT 'المُبلِّغ نفسه يتراجع عن بلاغه',
  `cancelled_at` datetime DEFAULT NULL,
  `cancellation_reason` text DEFAULT NULL,
  `rejected_by` int(10) UNSIGNED DEFAULT NULL COMMENT 'فريق الصيانة يرفض البلاغ من أساسه (مكرر/غير صحيح) — حالة نهائية مختلفة عن رفض الحل',
  `rejected_at` datetime DEFAULT NULL,
  `rejection_note` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `sla_breach_detected_at` datetime DEFAULT NULL COMMENT 'توقيت أول لحظة تجاوز المهلة فعلياً — يُسجَّل دائماً حتى لو التصعيد الفعلي معطَّلاً، لأغراض القياس والتقارير',
  `sla_paused_at` datetime DEFAULT NULL COMMENT 'NULL = الساعة تعمل حالياً، وإلا فهي مجمَّدة منذ هذا التوقيت',
  `sla_paused_seconds_total` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'إجمالي الثواني المتراكمة التي كانت فيها الساعة مجمَّدة عبر كل دورات الانتظار',
  `sla_pause_reason` varchar(255) DEFAULT NULL COMMENT 'سبب آخر تجميد (مثال: بانتظار شركة الضمان الخارجية)',
  `priority_original` enum('normal','urgent','critical') DEFAULT NULL COMMENT 'القيمة الأصلية للأولوية قبل أي إعادة تصنيف — تُسجَّل فقط عند أول تغيير',
  `priority_changed_by` int(10) UNSIGNED DEFAULT NULL,
  `priority_changed_at` datetime DEFAULT NULL,
  `priority_change_reason` varchar(255) DEFAULT NULL,
  `unresolvable_by` int(10) UNSIGNED DEFAULT NULL,
  `unresolvable_at` datetime DEFAULT NULL,
  `unresolvable_reason` text DEFAULT NULL,
  `returned_by_committee_by` int(10) UNSIGNED DEFAULT NULL,
  `returned_by_committee_at` datetime DEFAULT NULL,
  `returned_by_committee_note` text DEFAULT NULL,
  `executive_escalated_by` int(10) UNSIGNED DEFAULT NULL,
  `executive_escalated_at` datetime DEFAULT NULL,
  `executive_escalation_note` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

