CREATE TABLE `complaint_work_orders` (
  `id` int(10) UNSIGNED NOT NULL,
  `wo_number` varchar(50) NOT NULL COMMENT 'رقم أمر الإصلاح (مثل: WO/2026/001)',
  `complaint_id` int(10) UNSIGNED NOT NULL COMMENT 'يرتبط بالبلاغ - إلزامي',
  `contractor_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'الشركة المنفذة',
  `contractor_name` varchar(150) NOT NULL,
  `engineer_name` varchar(150) DEFAULT NULL COMMENT 'المهندس/الفني المنفذ',
  `wo_date` date NOT NULL COMMENT 'تاريخ أمر العمل',
  `expected_completion_date` date DEFAULT NULL,
  `actual_completion_date` date DEFAULT NULL,
  `service_power_supply` tinyint(1) DEFAULT 0,
  `service_electronic` tinyint(1) DEFAULT 0,
  `service_chemical` tinyint(1) DEFAULT 0,
  `service_planned_maintenance` tinyint(1) DEFAULT 0,
  `service_calibration` tinyint(1) DEFAULT 0,
  `service_equipment_fault` tinyint(1) DEFAULT 0,
  `service_spare_parts_required` tinyint(1) DEFAULT 0,
  `service_rescreening` tinyint(1) DEFAULT 0,
  `service_spare_parts_stock` tinyint(1) DEFAULT 0,
  `service_description` text DEFAULT NULL COMMENT 'شرح الأعطال والأعمال المنجزة (Service Done)',
  `manager_instructions` text DEFAULT NULL COMMENT 'توجيهات مدير الصيانة للشركة عند إنشاء أمر العمل',
  `follow_up_notes` text DEFAULT NULL COMMENT 'المتابعة (Follow Up)',
  `final_status` enum('completed','working_need_parts','need_secondary_parts','need_agent','pending') DEFAULT 'pending',
  `work_hours_day1` decimal(5,2) DEFAULT 0.00,
  `work_hours_day2` decimal(5,2) DEFAULT 0.00,
  `work_hours_day3` decimal(5,2) DEFAULT 0.00,
  `work_hours_total` decimal(5,2) DEFAULT 0.00,
  `work_completed` tinyint(1) DEFAULT 0 COMMENT 'هل تم إنجاز العمل؟ Yes=1/No=0',
  `status` enum('draft','sent_to_contractor','in_progress','pending_manager_approval','completed','rejected_by_manager','cancelled') NOT NULL DEFAULT 'draft',
  `created_by` int(10) UNSIGNED NOT NULL COMMENT 'مدير الصيانة الطبية الذي أنشأ الأمر',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `wo_type` enum('medical','general','it') NOT NULL DEFAULT 'medical' COMMENT 'نوع أمر العمل: medical=نموذج المشرق، general=نموذج الصيانة العامة، it=نموذج IT',
  `sent_to_contractor_at` datetime DEFAULT NULL COMMENT 'لحظة الإرسال للمقاول — يُجمِّد ساعة المهلة (SLA pause)',
  `contractor_received_at` datetime DEFAULT NULL,
  `approved_by` int(10) UNSIGNED DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejection_note` text DEFAULT NULL,
  `manager_return_note` text DEFAULT NULL,
  `manager_signature` text DEFAULT NULL COMMENT 'توقيع مدير الصيانة (base64 PNG)',
  `contractor_signature` text DEFAULT NULL COMMENT 'توقيع ممثل الشركة المقاولة (base64 PNG)',
  `contractor_signed_name` varchar(150) DEFAULT NULL,
  `general_work_nature` varchar(50) DEFAULT NULL COMMENT 'طبيعة العمل',
  `general_location_detail` varchar(255) DEFAULT NULL COMMENT 'تفاصيل الموقع',
  `general_affected_systems` text DEFAULT NULL COMMENT 'الأنظمة المتأثرة',
  `general_safety_measures` text DEFAULT NULL COMMENT 'إجراءات السلامة',
  `general_tools_used` text DEFAULT NULL COMMENT 'الأدوات',
  `general_materials_used` text DEFAULT NULL COMMENT 'المواد',
  `general_work_scope` varchar(50) DEFAULT NULL COMMENT 'نطاق العمل',
  `general_estimated_duration_hours` decimal(5,2) DEFAULT NULL COMMENT 'المدة المقدرة',
  `general_actual_duration_hours` decimal(5,2) DEFAULT NULL COMMENT 'المدة الفعلية',
  `general_team_size` int(11) DEFAULT NULL COMMENT 'عدد الفريق',
  `general_permit_required` tinyint(1) DEFAULT 0 COMMENT 'يتطلب تصريح',
  `general_permit_type` varchar(100) DEFAULT NULL COMMENT 'نوع التصريح',
  `general_building` varchar(100) DEFAULT NULL COMMENT 'المبنى',
  `general_floor` varchar(50) DEFAULT NULL COMMENT 'الطابق',
  `general_root_cause` text DEFAULT NULL COMMENT 'السبب الجذري',
  `general_recommendation` text DEFAULT NULL COMMENT 'التوصيات',
  `it_work_category` varchar(50) DEFAULT NULL COMMENT 'تصنيف العمل',
  `it_asset_type` varchar(100) DEFAULT NULL COMMENT 'نوع الأصل',
  `it_asset_tag` varchar(100) DEFAULT NULL COMMENT 'تاج الأصل',
  `it_ip_address` varchar(45) DEFAULT NULL COMMENT 'IP',
  `it_mac_address` varchar(17) DEFAULT NULL COMMENT 'MAC',
  `it_os_info` varchar(255) DEFAULT NULL COMMENT 'نظام التشغيل',
  `it_software_affected` text DEFAULT NULL COMMENT 'البرامج المتأثرة',
  `it_security_incident` tinyint(1) DEFAULT 0 COMMENT 'حادثة أمنية',
  `it_incident_severity` varchar(20) DEFAULT NULL COMMENT 'شدة الحادثة',
  `it_data_backup_done` tinyint(1) DEFAULT 0 COMMENT 'نسخ احتياطي',
  `it_data_loss` tinyint(1) DEFAULT 0 COMMENT 'فقدان بيانات',
  `it_user_impact_count` int(11) DEFAULT NULL COMMENT 'عدد المتأثرين',
  `it_downtime_hours` decimal(5,2) DEFAULT NULL COMMENT 'ساعات التعطل',
  `it_remote_session` tinyint(1) DEFAULT 0 COMMENT 'حل عن بُعد',
  `it_change_request_ref` varchar(100) DEFAULT NULL COMMENT 'طلب التغيير',
  `it_root_cause_category` varchar(50) DEFAULT NULL COMMENT 'تصنيف السبب',
  `it_preventive_action` text DEFAULT NULL COMMENT 'إجراء وقائي',
  `it_kb_article` text DEFAULT NULL COMMENT 'مقال KB',
  `assigned_user_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'الموظف المعيَّن للتنفيذ (التوجيه الداخلي) — يملك حقوق الشركة على أمره'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='أوامر الإصلاح - الصيانة الطبية فقط';

