  `require_oath_complete` tinyint(1) DEFAULT NULL COMMENT 'ÊÌÇæÒ global: ÅÞÑÇÑ ÅáÒÇãí ÞÈá ÇáÅÞÝÇá. NULL = ÇÓÊÎÏã global',
  `max_suspend_count` int(10) UNSIGNED DEFAULT NULL COMMENT 'ÊÌÇæÒ global: ÇáÍÏ ÇáÃÞÕì ááÊÚáíÞÇÊ. NULL = ÇÓÊÎÏã global',
  `block_audit_undocumented_room` tinyint(1) DEFAULT NULL COMMENT 'ÊÌÇæÒ global: ãäÚ ÌÑÏ ÛÑÝÉ ÛíÑ ãæËÞÉ. NULL = ÇÓÊÎÏã global',
  `dept_required_before_lock` tinyint(1) DEFAULT NULL COMMENT 'ÊÌÌÇæÒ global: ÞÓã ÅáÒÇãí ÞÈá ÇáÞÝá. NULL = ÇÓÊÎÏã global',
  `settings_override_note` varchar(500) DEFAULT NULL COMMENT 'ÓÈÈ ÊÌÇæÒ ÇáÅÚÏÇÏÇÊ ÇáÚÇãÉ áåÐå ÇáÌáÓÉ',
