--
-- بنية الجدول `inventory_session_members`
--

CREATE TABLE `inventory_session_members` (
  `session_id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `role` enum('leader','member','observer') NOT NULL DEFAULT 'member',
  `assigned_scope` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'نطاق العضو: dept_ids أو buildings (NULL = كل النطاق)' CHECK (json_valid(`assigned_scope`)),
  `custom_tasks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`custom_tasks`)),
  `assigned_departments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'للوضع split_by_member: الأقسام المسؤول عنها هذا العضو' CHECK (json_valid(`assigned_departments`)),
  `assigned_locations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'geofencing: المواقع الفيزيائية المسموح بها. NULL=كل مواقع القسم' CHECK (json_valid(`assigned_locations`)),
  `primary_team_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'FK -> inventory_session_teams: الفريق الأساسي للعضو',
  `joined_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='أعضاء لجان الجرد وأدوارهم';

