  `catalog_type` varchar(50) NOT NULL DEFAULT 'medical_equipment' COMMENT 'medical_equipment | pharmaceuticals | laboratory | medical_supplies',
  `item_no` varchar(30) DEFAULT NULL COMMENT 'رقم الصنف الرسمي للطلب',
  `generic_code` varchar(30) DEFAULT NULL COMMENT 'الكود التصنيفي العام (GMDN-style)',
  `description_en` varchar(500) NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `sub_category` varchar(100) DEFAULT NULL,
  `asset_category` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `description_normalized` varchar(500) DEFAULT NULL,
  `description_ar` varchar(500) DEFAULT NULL COMMENT 'الوصف بالعربية (مترجم من description_en عبر Groq)',
  `category_ar` varchar(100) DEFAULT NULL COMMENT 'الفئة بالعربية',
  `sub_category_ar` varchar(100) DEFAULT NULL COMMENT 'الفئة الفرعية بالعربية',
  `translated_at` datetime DEFAULT NULL COMMENT 'تاريخ الترجمة',
  `translated_by` varchar(50) DEFAULT NULL COMMENT 'مصدر الترجمة (groq-llama-3.3-70b, manual, ...)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

