--
-- بنية الجدول `nupco_sync_log`
--

CREATE TABLE `nupco_sync_log` (
  `id` int(10) UNSIGNED NOT NULL,
  `file_name` varchar(255) NOT NULL COMMENT 'اسم الملف الأصلي (مثل NUPCOs-Medical-Equipment-Catalogue-April-2026.xlsx)',
  `file_size` int(10) UNSIGNED DEFAULT NULL COMMENT 'حجم الملف بالبايت',
  `file_hash` char(64) DEFAULT NULL COMMENT 'SHA256 للملف — لمنع المزامنة المكررة لنفس الملف',
  `sheet_name` varchar(100) DEFAULT NULL COMMENT 'اسم الـ sheet في Excel',
  `rows_in_file` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'عدد الصفوف في الملف (بدون header)',
  `matched_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'عدد السجلات المتطابقة تماماً',
  `new_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'عدد الأصناف الجديدة المُضافة',
  `updated_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'عدد السجلات المُحدّثة',
  `not_in_excel_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'عدد السجلات الموجودة في DB لكن غير موجودة في الملف',
  `error_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'عدد الأخطاء أثناء التطبيق',
  `status` enum('uploaded','previewed','applied','failed','cancelled') NOT NULL DEFAULT 'uploaded' COMMENT 'uploaded=تم الرفع فقط, previewed=تم العرض, applied=تم التطبيق, failed=فشل, cancelled=ألغاه المستخدم',
  `error_log` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'JSON array للأخطاء (إن وُجدت)' CHECK (json_valid(`error_log`)),
  `sync_date` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'تاريخ/وقت المزامنة',
  `applied_at` datetime DEFAULT NULL COMMENT 'تاريخ/وقت التطبيق الفعلي',
  `synced_by` int(10) UNSIGNED NOT NULL COMMENT 'FK → users.id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجل مزامنات NUPCO (رفع ومقارنة وتطبيق)';

-- --------------------------------------------------------

--
-- بنية الجدول `nupco_translation_log`
--

CREATE TABLE `nupco_translation_log` (
  `id` int(10) UNSIGNED NOT NULL,
  `nupco_id` int(10) UNSIGNED NOT NULL COMMENT 'FK → nupco_catalog.id',
  `field_name` enum('description_ar','category_ar','sub_category_ar') NOT NULL COMMENT 'الحقل المُترجَم',
  `source_text` varchar(500) NOT NULL COMMENT 'النص الأصلي (snapshot)',
  `translated_text` varchar(500) NOT NULL COMMENT 'الترجمة',
  `model` varchar(50) NOT NULL COMMENT 'الموديل (groq-llama-3.3-70b-versatile مثلاً)',
  `status` enum('ok','failed') NOT NULL DEFAULT 'ok',
  `error_msg` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='سجل ترجمات NUPCO — للمراجعة وإعادة المحاولة';

