--
-- Structure for view `v_nupco_translation_status`
--
DROP TABLE IF EXISTS `v_nupco_translation_status`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_nupco_translation_status`  AS SELECT count(0) AS `total_rows`, sum(case when `nupco_catalog`.`description_ar` is not null and trim(`nupco_catalog`.`description_ar`) <> '' then 1 else 0 end) AS `desc_translated`, sum(case when `nupco_catalog`.`category_ar` is not null and trim(`nupco_catalog`.`category_ar`) <> '' then 1 else 0 end) AS `cat_translated`, sum(case when `nupco_catalog`.`sub_category_ar` is not null and trim(`nupco_catalog`.`sub_category_ar`) <> '' then 1 else 0 end) AS `subcat_translated`, sum(case when `nupco_catalog`.`description_ar` is null or trim(`nupco_catalog`.`description_ar`) = '' then 1 else 0 end) AS `desc_pending`, max(`nupco_catalog`.`translated_at`) AS `last_translated_at` FROM `nupco_catalog` ;

